  initVirtualScroll()
  setupFolderClickInterception()
  setupEmailSelectionTracking()
  setupMailListViewToggle()
  setupContactsList()
  setupMailFilters()
  setupTableColumns()
  setupSSE()
  // Leaving the page closes its event stream at once. Otherwise the browser
