    if (quoted) { if (c === '"') quoted = false; continue }
    if (c === '"') quoted = true
    else if (c === "(") depth++
    else if (c === ")" && depth > 0) depth--
    else if (depth > 0) continue
    else if (c === "<") angle = true
    else if (c === ">") angle = false
    else if (!angle && (c === "," || c === ";" || c === "\n")) cut(i)
